fun ConsumerRecord<SpecificRecord, SpecificRecord>.toChangedCatalogData(): ChangedData<ChangedCatalogDocument> {
    val key = this.key() as CatalogCdcKey
    val value = this.value() as CatalogCdcEnvelope

    return ChangedData(
        id = (key.`id$1` ?: value.after?.`id$1` ?: value.before?.`id$1`!!).toString(),
        op = convertOp(value.op),
        beforeData = value.before?.toChangedCatalogDocument(),
        afterData = value.after?.toChangedCatalogDocument(),
        partition = this.partition(),
        offset = this.offset(),
    )
}

fun ConsumerRecord<SpecificRecord, SpecificRecord>.toChangedProductData(): ChangedData<ChangedProductDocument> {
    val key = this.key() as ProductCdcKey
    val value = this.value() as ProductCdcEnvelope
    return ChangedData(
        id = (key.`id$1` ?: value.after?.`id$1` ?: value.before?.`id$1`!!).toString(),
        op = convertOp(value.op),
        beforeData = value.before?.toChangedProductDocument(),
        afterData = value.after?.toChangedProductDocument(),
        partition = this.partition(),
        offset = this.offset(),
    )
}

private fun convertOp(value: String): Operation =
    when (value) {
        "c" -> Operation.CREATE
        "u" -> Operation.UPDATE
        "d" -> Operation.DELETE
        else -> throw IllegalArgumentException("Unknown operation type.")
    }

private fun Catalog.toChangedCatalogDocument() =
