            isDisplayed = isDisplayed,
            isPriceLocked = isPriceLocked,
            registeredAt = registeredAt,
            updatedAt = updatedAt,
            createdAt = createdAt,
            channelDatas =
                ChangedCatalogDocument.ChannelDatas(
                    danawa = channelDatas["DANAWA"]?.run { this.toCatalogChannelData() },
                    enuri = channelDatas["ENURI"]?.run { this.toCatalogChannelData() },
                ),
        )
    }

private fun CdcEnvelopCatalogChannelData.toCatalogChannelData(): ChangedCatalogDocument.ChannelDatas.ChannelData =
    ChangedCatalogDocument.ChannelDatas.ChannelData(
        catalogStatus = catalogStatus,
        price =
            price?.let {
