package com.cowave.search.inbound_adapter.handler.listener

import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.ProductCdcEnvelope
import com.cowave.search.application.index.service.ProductIndexApplicationService
import com.cowave.search.inbound_adapter.handler.ConsumerCallbackManager
import com.cowave.search.inbound_adapter.handler.mapper.toChangedProductData
import com.cowave.shared.utils.logger
import org.apache.avro.specific.SpecificRecord
import org.apache.kafka.clients.consumer.Consumer
import org.apache.kafka.clients.consumer.ConsumerRecord
import org.springframework.kafka.listener.BatchAcknowledgingConsumerAwareMessageListener
import org.springframework.kafka.support.Acknowledgment

class ProductDynamicIndexListener(
    private val productIndexApplicationService: ProductIndexApplicationService,
    groupId: String,
    consumerCallbackManager: ConsumerCallbackManager,
) : FlinkCdcBatchListener(groupId, consumerCallbackManager),
    BatchAcknowledgingConsumerAwareMessageListener<SpecificRecord, SpecificRecord> {
    private val logger by logger()

    override fun onMessage(
        data: List<ConsumerRecord<SpecificRecord, SpecificRecord>>,
        acknowledgment: Acknowledgment?,
        consumer: Consumer<*, *>,
    ) {
        runCatching {
            val changedDocuments =
                data
                    .filter { record ->
                        val envelope = record.value() as ProductCdcEnvelope
                        val product = envelope.after ?: envelope.before
                        product != null && product.categoryId > 0
                    }.map { it.toChangedProductData() }

            productIndexApplicationService.indexProducts(changedDocuments)
        }.onSuccess {
            acknowledgment?.acknowledge()
            rewindIfNeeded()
        }.onFailure { ex ->
            logger.error(ex) { "Failed to index products" }
        }.getOrThrow()
    }
}

package com.cowave.search.inbound_adapter.handler.config

import com.cowave.search.application.index.service.CatalogIndexApplicationService
import com.cowave.search.application.index.service.ProductIndexApplicationService
import com.cowave.search.inbound_adapter.handler.ConsumerCallbackManager
import com.cowave.search.inbound_adapter.handler.dto.ConsumerGroupOffsetSnapshot
import com.cowave.search.inbound_adapter.handler.listener.CatalogDynamicIndexListener
import com.cowave.search.inbound_adapter.handler.listener.DynamicIndexAdminListener
import com.cowave.search.inbound_adapter.handler.listener.ProductDynamicIndexListener
import org.apache.avro.specific.SpecificRecord
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.kafka.listener.ConcurrentMessageListenerContainer

@Configuration
class DynamicIndexConfig(
    private val dynamicIndexerProperties: DynamicIndexerProperties,
    private val catalogIndexApplicationService: CatalogIndexApplicationService,
    private val productIndexApplicationService: ProductIndexApplicationService,
    private val consumerCallbackManager: ConsumerCallbackManager,
) {
    @Bean
    fun catalogDynamicIndexKafkaListenerContainer(): ConcurrentMessageListenerContainer<SpecificRecord, SpecificRecord> {
        val listener =
            CatalogDynamicIndexListener(
                catalogIndexApplicationService = catalogIndexApplicationService,
                consumerCallbackManager = consumerCallbackManager,
                groupId = dynamicIndexerProperties.catalogCdc.groupId,
            )
        return DynamicIndexContainerFactory.createCdcContainer(
            dynamicIndexConsumer = dynamicIndexerProperties.catalogCdc,
            listener = listener,
        )
    }

    @Bean
    fun productDynamicIndexKafkaListenerContainer(): ConcurrentMessageListenerContainer<SpecificRecord, SpecificRecord> {
        val listener =
            ProductDynamicIndexListener(
                productIndexApplicationService = productIndexApplicationService,
                consumerCallbackManager = consumerCallbackManager,
                groupId = dynamicIndexerProperties.productCdc.groupId,
            )
        return DynamicIndexContainerFactory.createCdcContainer(
            dynamicIndexConsumer = dynamicIndexerProperties.productCdc,
            listener = listener,
        )
    }

    @Bean
    fun dynamicIndexAdminKafkaListenerContainer(): ConcurrentMessageListenerContainer<String, ConsumerGroupOffsetSnapshot> {
        val listener = DynamicIndexAdminListener(consumerCallbackManager)
        return DynamicIndexContainerFactory.createAdminContainer(
            dynamicIndexAdminConsumer = dynamicIndexerProperties.indexerAdmin,
            listener = listener,
        )
    }
}

